#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> digits(N);
    for (int &d : digits) cin >> d;

    for (int k = 1; k <= N; ++k) {
        if (digits[0] == 0) continue;

        string start;
        for (int i = 0; i < k; ++i)
            start += char('0' + digits[i]);

        string current = start;
        int pos = 0;
        bool valid = true;

        while (pos < N) {
            if (pos + (int)current.size() > N) {
                valid = false;
                break;
            }

            for (int i = 0; i < (int)current.size(); ++i) {
                if (digits[pos + i] != current[i] - '0') {
                    valid = false;
                    break;
                }
            }

            if (!valid) break;
            pos += current.size();

            if (pos == N) break;

            int i = (int)current.size() - 1;
            while (i >= 0 && current[i] == '9') {
                current[i] = '0';
                --i;
            }
            if (i < 0)
                current = '1' + current;
            else
                ++current[i];
        }

        if (valid && pos == N) {
            cout << start << '\n';
            return 0;
        }
    }

    return 0;
}
